"use client";

/**
 * Shared route-level error boundary UI.
 *
 * Every `error.tsx` in the catalogue renders this, so a route segment
 * needs a ten-line wrapper instead of its own copy of the same layout,
 * reporting call, console log, and error classification. Items that
 * ship an `error.tsx` depend on this component the way `dashboard`
 * depends on `team-settings`' `lib/team.ts` — install `route-error`
 * first.
 *
 * Error reporting goes through the `reportRouteError` seam
 * (`@/lib/error-reporting`), which is a no-op until you bind a
 * reporter — registry items never import an SDK directly.
 *
 * The message is chosen by `getErrorType`, which maps a network blip,
 * a timeout, and a server fault to distinct copy; `fallback` lets a
 * route supply its own key for the "none of the above" case (e.g. the
 * chat item passes `conversation`).
 */

import { useEffect } from "react";
import { AlertCircle } from "lucide-react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { reportRouteError } from "@/lib/error-reporting";
import { getErrorType } from "@/lib/errors/get-error-type";

export interface RouteErrorProps {
  error: Error & { digest?: string };
  reset: () => void;
  /** Short identifier for the route segment, used in logs and reports. */
  scope: string;
  /** Where the secondary button goes (default: `/dashboard`). */
  homeHref?: string;
  /** Message key for the secondary button's label. */
  homeKey?: string;
  /**
   * Message key used when no classification rule matches — for a route
   * with copy of its own. Defaults to `generic`.
   */
  fallback?: string;
  /**
   * Full-screen layout instead of the in-shell inset one. Set this for
   * boundaries that render outside the `(app)` shell.
   */
  fullScreen?: boolean;
}

export function RouteError({
  error,
  reset,
  scope,
  homeHref = "/dashboard",
  homeKey = "goToDashboard",
  fallback,
  fullScreen = false,
}: RouteErrorProps) {
  const t = useTranslations("route-error");

  useEffect(() => {
    reportRouteError(error, { scope });
    console.error(`[${scope}] error boundary caught:`, {
      message: error.message,
      digest: error.digest,
    });
  }, [error, scope]);

  const errorType = getErrorType(error, fallback);

  return (
    <div
      className={
        fullScreen
          ? "flex min-h-screen items-center justify-center p-4"
          : "flex min-h-96 items-center justify-center p-8"
      }
    >
      <div className="w-full max-w-md space-y-4">
        <Alert variant="destructive">
          <AlertCircle className="size-4" />
          <AlertDescription className="mt-2">{t(errorType)}</AlertDescription>
        </Alert>

        <div className="flex justify-center gap-3">
          <Button onClick={reset}>{t("retry")}</Button>
          <Button
            variant="outline"
            render={<Link href={homeHref} />}
            nativeButton={false}
          >
            {t(homeKey)}
          </Button>
        </div>
      </div>
    </div>
  );
}

/**
 * Classifies an error into a known category from its message/digest.
 *
 * Route-level error boundaries use this to pick a translation key in
 * the `route-error` namespace, so a network blip and a server fault
 * don't both render the same shrug. Central rather than per-route:
 * the classification is the same everywhere, only the copy differs.
 */

export type ErrorType = "generic" | "network" | "timeout" | "server";

/**
 * Classifies an error, falling back to either the standard `generic`
 * key or a route-specific one (e.g. `conversation`) when no rule
 * matches. The type parameter narrows the return type so callers get
 * full type-checking on the fallback they pass in.
 */
export function getErrorType<F extends string = "generic">(
  error: Error & { digest?: string },
  fallback?: F
): ErrorType | F {
  const message = error.message?.toLowerCase() ?? "";
  const digest = error.digest?.toLowerCase() ?? "";

  if (
    message.includes("network") ||
    message.includes("fetch") ||
    digest.includes("network")
  ) {
    return "network";
  }
  if (message.includes("timeout") || digest.includes("timeout")) {
    return "timeout";
  }
  if (
    message.includes("500") ||
    message.includes("503") ||
    digest.includes("server")
  ) {
    return "server";
  }
  return (fallback ?? "generic") as F;
}

/**
 * Error-reporting seam — consumer-owned.
 *
 * `RouteError` calls this from every route-level error boundary. The
 * default is a no-op on purpose: registry items never depend on an
 * error-reporting SDK, so a fresh install has nothing to configure and
 * nothing to pay for. Bind your own reporter here and every boundary
 * in the app starts reporting, with no component edit.
 *
 * With Sentry, for example:
 *
 *   import * as Sentry from "@sentry/nextjs";
 *
 *   export function reportRouteError(
 *     error: Error & { digest?: string },
 *     context: RouteErrorContext
 *   ) {
 *     Sentry.captureException(error, { tags: { scope: context.scope } });
 *   }
 *
 * This runs inside a `useEffect` in a client component, so it must not
 * throw — a reporter that fails should swallow its own failure rather
 * than take the error screen down with it.
 */

export interface RouteErrorContext {
  /** Short identifier for the route segment that failed. */
  scope: string;
}

export function reportRouteError(
  _error: Error & { digest?: string },
  _context: RouteErrorContext
): void {
  // No-op by default. See the doc comment above.
}

"use client";

/**
 * Error boundary for the whole `(app)` route group — the backstop for
 * any authenticated page whose own segment doesn't ship one.
 */

import { RouteError } from "@/components/shared/route-error";

export default function AppError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return <RouteError error={error} reset={reset} scope="app" />;
}

/**
 * 404 page for the `[locale]` segment — a server component, since
 * there is nothing dynamic about "this route doesn't exist".
 */

import { getTranslations } from "next-intl/server";

import { Link } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";

export default async function NotFound() {
  const t = await getTranslations("route-error");

  return (
    <div className="flex min-h-screen items-center justify-center p-4">
      <div className="max-w-md space-y-4 text-center">
        <h2 className="text-2xl font-semibold">{t("notFound.title")}</h2>
        <p className="text-muted-foreground">{t("notFound.description")}</p>
        <Button render={<Link href="/dashboard" />} nativeButton={false}>
          {t("goToDashboard")}
        </Button>
      </div>
    </div>
  );
}

"use client";

/**
 * Last-resort boundary: a failure in the root layout itself, which
 * replaces the whole document.
 *
 * Deliberately static English and inline styles — this renders *above*
 * `NextIntlClientProvider` and outside the `[locale]` segment, so there
 * is no translator and no guarantee the stylesheet loaded. That is the
 * one documented exception to the i18n-native rule; every other
 * error surface in the catalogue is translated. Keep it dependency-free
 * for the same reason: whatever broke may be one of the dependencies.
 *
 * Reporting still goes through the `reportRouteError` seam, so a
 * global crash reaches the same reporter as every other boundary.
 */

import { useEffect } from "react";

import { reportRouteError } from "@/lib/error-reporting";

export default function GlobalError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    reportRouteError(error, { scope: "global" });
    console.error("[global] error boundary caught:", {
      message: error.message,
      digest: error.digest,
    });
  }, [error]);

  return (
    <html lang="en">
      <body
        style={{
          fontFamily: "system-ui, sans-serif",
          display: "flex",
          minHeight: "100vh",
          alignItems: "center",
          justifyContent: "center",
          margin: 0,
        }}
      >
        <div
          style={{ maxWidth: "28rem", padding: "2rem", textAlign: "center" }}
        >
          <h2 style={{ fontSize: "1.25rem", marginBottom: "0.5rem" }}>
            Something went wrong
          </h2>
          <p style={{ color: "#666", marginBottom: "1.5rem" }}>
            The application failed to load. Try again, and if it keeps
            happening, contact support.
          </p>
          <button
            type="button"
            onClick={() => reset()}
            style={{
              padding: "0.5rem 1rem",
              borderRadius: "0.375rem",
              border: "1px solid #ccc",
              background: "#111",
              color: "#fff",
              cursor: "pointer",
            }}
          >
            Try again
          </button>
        </div>
      </body>
    </html>
  );
}
